{
  "name": "TuKu - Image Processor",
  "description": "A powerful, privacy-friendly online image processing tool. Upload, edit, convert, and compress images securely on your own server."
}

export enum ImageFormat {
  ORIGINAL = 'original',
  JPEG = 'jpeg',
  PNG = 'png',
  WEBP = 'webp',
  AVIF = 'avif'
}

export interface ProcessOptions {
  format: ImageFormat;
  quality: number; // 1-100
  width: number | null;
  height: number | null;
  maintainAspectRatio: boolean;
  resizeMode: 'cover' | 'contain' | 'fill' | 'inside' | 'outside';
  rotate: number; // degrees
  flipX: boolean;
  flipY: boolean;
  grayscale: boolean;
  blur: number; // 0-100
  sharpen: boolean;
  watermarkText: string;
}

export interface UploadResponse {
  id: string;
  filename: string;
  url: string;
  originalName: string;
  size: number;
  width?: number;
  height?: number;
}

export interface ProcessResponse {
  url: string;
  filename: string;
  size: number;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useRef, useState } from 'react';

interface DropzoneProps {
  onFileSelect: (file: File) => void;
  isUploading: boolean;
}

export const Dropzone: React.FC<DropzoneProps> = ({ onFileSelect, isUploading }) => {
  const [isDragOver, setIsDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      validateAndUpload(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      validateAndUpload(e.target.files[0]);
    }
  };

  const validateAndUpload = (file: File) => {
    const validTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/bmp', 'image/heic', 'image/gif'];
    if (!validTypes.includes(file.type)) {
      alert('Format not supported. Please upload JPG, PNG, WEBP, BMP, or GIF.');
      return;
    }
    if (file.size > 20 * 1024 * 1024) {
      alert('File too large. Max size is 20MB.');
      return;
    }
    onFileSelect(file);
  };

  return (
    <div
      onClick={() => !isUploading && fileInputRef.current?.click()}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`
        w-full h-64 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center cursor-pointer transition-all duration-300
        ${isDragOver 
          ? 'border-indigo-500 bg-indigo-50 scale-[1.02]' 
          : 'border-slate-300 bg-white hover:border-indigo-400 hover:bg-slate-50'}
        ${isUploading ? 'opacity-50 pointer-events-none' : ''}
      `}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleChange} 
        className="hidden" 
        accept="image/jpeg,image/png,image/webp,image/bmp,image/gif"
      />

      {isUploading ? (
        <div className="flex flex-col items-center animate-pulse">
           <svg className="animate-spin h-10 w-10 text-indigo-500 mb-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
           <p className="text-lg font-medium text-slate-600">Uploading...</p>
        </div>
      ) : (
        <>
          <div className="bg-indigo-100 p-4 rounded-full mb-4">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8 text-indigo-600">
              <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5m-13.5-9L12 3m0 0l4.5 4.5M12 3v13.5" />
            </svg>
          </div>
          <p className="text-xl font-semibold text-slate-700 mb-2">Click to Upload or Drag & Drop</p>
          <p className="text-sm text-slate-500">JPG, PNG, WEBP, BMP up to 20MB</p>
        </>
      )}
    </div>
  );
};

import React from 'react';
import { ImageFormat, ProcessOptions } from '../types';

interface ControlsProps {
  options: ProcessOptions;
  setOptions: React.Dispatch<React.SetStateAction<ProcessOptions>>;
  onProcess: () => void;
  isProcessing: boolean;
  originalDimensions?: { width: number; height: number };
}

export const Controls: React.FC<ControlsProps> = ({ 
  options, 
  setOptions, 
  onProcess, 
  isProcessing,
  originalDimensions 
}) => {

  const updateOption = <K extends keyof ProcessOptions>(key: K, value: ProcessOptions[K]) => {
    setOptions(prev => ({ ...prev, [key]: value }));
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full overflow-hidden">
      <div className="p-4 border-b border-slate-100 bg-slate-50">
        <h2 className="font-semibold text-slate-800 flex items-center">
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5 mr-2 text-indigo-600">
            <path d="M10 3.75a2 2 0 10-4 0 2 2 0 004 0zM17.25 4.5a.75.75 0 00-1.5 0h-2.5a.75.75 0 000 1.5h2.5a.75.75 0 001.5 0zm-14.5 0a.75.75 0 000 1.5h2.5a.75.75 0 000-1.5h-2.5zM10 8.5a2 2 0 10-4 0 2 2 0 004 0zM17.25 9.25a.75.75 0 00-1.5 0h-2.5a.75.75 0 000 1.5h2.5a.75.75 0 001.5 0zm-14.5 0a.75.75 0 000 1.5h2.5a.75.75 0 000-1.5h-2.5zM10 13.25a2 2 0 10-4 0 2 2 0 004 0zM17.25 14a.75.75 0 00-1.5 0h-2.5a.75.75 0 000 1.5h2.5a.75.75 0 001.5 0zm-14.5 0a.75.75 0 000 1.5h2.5a.75.75 0 000-1.5h-2.5z" />
          </svg>
          Settings
        </h2>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {/* Format & Quality */}
        <section>
          <label className="block text-sm font-medium text-slate-700 mb-2">Format</label>
          <div className="grid grid-cols-3 gap-2">
            {[ImageFormat.ORIGINAL, ImageFormat.JPEG, ImageFormat.PNG, ImageFormat.WEBP].map(fmt => (
              <button
                key={fmt}
                onClick={() => updateOption('format', fmt)}
                className={`px-3 py-2 text-sm rounded-md border ${
                  options.format === fmt 
                    ? 'bg-indigo-600 text-white border-indigo-600' 
                    : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'
                }`}
              >
                {fmt.toUpperCase()}
              </button>
            ))}
          </div>
        </section>

        {options.format !== ImageFormat.PNG && (
          <section>
            <div className="flex justify-between mb-2">
              <label className="text-sm font-medium text-slate-700">Quality</label>
              <span className="text-sm text-slate-500">{options.quality}%</span>
            </div>
            <input
              type="range"
              min="10"
              max="100"
              value={options.quality}
              onChange={(e) => updateOption('quality', Number(e.target.value))}
              className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
            />
          </section>
        )}

        {/* Dimensions */}
        <section>
          <label className="block text-sm font-medium text-slate-700 mb-2">Resize</label>
          <div className="flex gap-2 items-center mb-3">
            <div className="relative w-full">
              <input
                type="number"
                placeholder={originalDimensions?.width?.toString() || 'Width'}
                value={options.width || ''}
                onChange={(e) => updateOption('width', e.target.value ? Number(e.target.value) : null)}
                className="w-full pl-3 pr-8 py-2 text-sm border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
              />
              <span className="absolute right-3 top-2 text-xs text-slate-400">px</span>
            </div>
            <span className="text-slate-400">×</span>
            <div className="relative w-full">
              <input
                type="number"
                placeholder={originalDimensions?.height?.toString() || 'Height'}
                value={options.height || ''}
                onChange={(e) => updateOption('height', e.target.value ? Number(e.target.value) : null)}
                className="w-full pl-3 pr-8 py-2 text-sm border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
              />
              <span className="absolute right-3 top-2 text-xs text-slate-400">px</span>
            </div>
          </div>
          <div className="flex items-center">
            <input
              type="checkbox"
              id="aspect"
              checked={options.maintainAspectRatio}
              onChange={(e) => updateOption('maintainAspectRatio', e.target.checked)}
              className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
            />
            <label htmlFor="aspect" className="ml-2 text-sm text-slate-600">Maintain Aspect Ratio</label>
          </div>
        </section>

        {/* Adjustments */}
        <section>
          <label className="block text-sm font-medium text-slate-700 mb-2">Transform</label>
          <div className="flex gap-2 mb-3">
             <button 
               onClick={() => updateOption('rotate', (options.rotate - 90) % 360)}
               className="flex-1 py-2 border border-slate-300 rounded-md text-sm hover:bg-slate-50 text-slate-700"
             >
               ↺ -90°
             </button>
             <button 
               onClick={() => updateOption('rotate', (options.rotate + 90) % 360)}
               className="flex-1 py-2 border border-slate-300 rounded-md text-sm hover:bg-slate-50 text-slate-700"
             >
               ↻ +90°
             </button>
          </div>
          <div className="flex gap-2">
            <button 
              onClick={() => updateOption('flipX', !options.flipX)}
              className={`flex-1 py-2 border rounded-md text-sm ${options.flipX ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}
            >
              Flip H
            </button>
            <button 
              onClick={() => updateOption('flipY', !options.flipY)}
              className={`flex-1 py-2 border rounded-md text-sm ${options.flipY ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}
            >
              Flip V
            </button>
          </div>
        </section>

        {/* Filters */}
        <section>
           <label className="block text-sm font-medium text-slate-700 mb-2">Filters</label>
           <div className="space-y-3">
             <div className="flex items-center justify-between">
                <span className="text-sm text-slate-600">Grayscale</span>
                <input 
                  type="checkbox" 
                  checked={options.grayscale}
                  onChange={(e) => updateOption('grayscale', e.target.checked)}
                  className="toggle-checkbox h-5 w-5 text-indigo-600 rounded focus:ring-indigo-500"
                />
             </div>
             <div className="flex items-center justify-between">
                <span className="text-sm text-slate-600">Sharpen</span>
                <input 
                  type="checkbox" 
                  checked={options.sharpen}
                  onChange={(e) => updateOption('sharpen', e.target.checked)}
                  className="toggle-checkbox h-5 w-5 text-indigo-600 rounded focus:ring-indigo-500"
                />
             </div>
             <div>
                <div className="flex justify-between mb-1">
                  <span className="text-sm text-slate-600">Blur</span>
                  <span className="text-xs text-slate-400">{options.blur}px</span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="20"
                  step="0.5"
                  value={options.blur}
                  onChange={(e) => updateOption('blur', Number(e.target.value))}
                  className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                />
             </div>
           </div>
        </section>

        {/* Watermark */}
        <section>
           <label className="block text-sm font-medium text-slate-700 mb-2">Watermark</label>
           <input
             type="text"
             placeholder="Enter text..."
             value={options.watermarkText}
             onChange={(e) => updateOption('watermarkText', e.target.value)}
             className="w-full px-3 py-2 text-sm border border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500"
           />
        </section>
      </div>

      <div className="p-4 border-t border-slate-100 bg-slate-50">
        <button
          onClick={onProcess}
          disabled={isProcessing}
          className={`w-full py-3 px-4 rounded-lg font-semibold text-white shadow-lg transition-all
            ${isProcessing 
              ? 'bg-indigo-400 cursor-not-allowed' 
              : 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-500/30 active:scale-[0.98]'
            }
          `}
        >
          {isProcessing ? 'Processing...' : 'Process Image'}
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Dropzone } from './components/Dropzone';
import { Controls } from './components/Controls';
import { ImageFormat, ProcessOptions, UploadResponse, ProcessResponse } from './types';

const defaultOptions: ProcessOptions = {
  format: ImageFormat.ORIGINAL,
  quality: 85,
  width: null,
  height: null,
  maintainAspectRatio: true,
  resizeMode: 'cover',
  rotate: 0,
  flipX: false,
  flipY: false,
  grayscale: false,
  blur: 0,
  sharpen: false,
  watermarkText: ''
};

function App() {
  const [currentFile, setCurrentFile] = useState<UploadResponse | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [options, setOptions] = useState<ProcessOptions>(defaultOptions);
  const [result, setResult] = useState<ProcessResponse | null>(null);

  const handleFileUpload = async (file: File) => {
    setIsUploading(true);
    setResult(null);
    const formData = new FormData();
    formData.append('image', file);

    try {
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) throw new Error('Upload failed');

      const data: UploadResponse = await response.json();
      setCurrentFile(data);
      // Reset sensitive options but keep generic ones if desired
      setOptions({
        ...defaultOptions,
        width: data.width || null,
        height: data.height || null
      });
    } catch (error) {
      console.error(error);
      alert('Failed to upload image');
    } finally {
      setIsUploading(false);
    }
  };

  const handleProcess = async () => {
    if (!currentFile) return;

    setIsProcessing(true);
    try {
      const response = await fetch('/api/process', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: currentFile.id,
          options
        })
      });

      if (!response.ok) throw new Error('Processing failed');

      const data: ProcessResponse = await response.json();
      setResult(data);
    } catch (error) {
      console.error(error);
      alert('Failed to process image');
    } finally {
      setIsProcessing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleReset = () => {
    setCurrentFile(null);
    setResult(null);
    setOptions(defaultOptions);
  };

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 py-3 px-6 shadow-sm z-10">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-2" onClick={handleReset} role="button">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center">
               <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5 text-white">
                 <path strokeLinecap="round" strokeLinejoin="round" d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456zM16.894 20.567L16.5 21.75l-.394-1.183a2.25 2.25 0 00-1.423-1.423L13.5 18.75l1.183-.394a2.25 2.25 0 001.423-1.423l.394-1.183.394 1.183a2.25 2.25 0 001.423 1.423l1.183.394-1.183.394a2.25 2.25 0 00-1.423 1.423z" />
               </svg>
            </div>
            <h1 className="text-xl font-bold tracking-tight text-slate-800">TuKu <span className="font-normal text-slate-400">| 图酷</span></h1>
          </div>
          <div className="text-sm text-slate-500">
             Fast, secure image processing on your server
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden bg-slate-50 relative">
        <div className="absolute inset-0 overflow-y-auto">
          <div className="max-w-7xl mx-auto p-6 h-full min-h-[calc(100vh-64px)]">

            {!currentFile ? (
              <div className="h-full flex flex-col justify-center items-center max-w-2xl mx-auto">
                <div className="w-full text-center mb-10">
                   <h2 className="text-4xl font-extrabold text-slate-800 mb-4">Edit & Convert Images Instantly</h2>
                   <p className="text-lg text-slate-600">Drag and drop your images to start converting, resizing, and optimizing.</p>
                </div>
                <Dropzone onFileSelect={handleFileUpload} isUploading={isUploading} />
              </div>
            ) : (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-full pb-10">
                {/* Left: Controls */}
                <div className="lg:col-span-1 h-full max-h-[800px]">
                  <Controls 
                    options={options} 
                    setOptions={setOptions} 
                    onProcess={handleProcess}
                    isProcessing={isProcessing}
                    originalDimensions={{ width: currentFile.width || 0, height: currentFile.height || 0 }}
                  />
                </div>

                {/* Right: Preview & Result */}
                <div className="lg:col-span-2 flex flex-col gap-6">
                  {/* Preview Area */}
                  <div className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm flex-1 flex flex-col items-center justify-center relative overflow-hidden min-h-[400px]">
                    <div className="absolute inset-0" style={{
                      backgroundImage: 'linear-gradient(45deg, #f1f5f9 25%, transparent 25%), linear-gradient(-45deg, #f1f5f9 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #f1f5f9 75%), linear-gradient(-45deg, transparent 75%, #f1f5f9 75%)',
                      backgroundSize: '20px 20px',
                      backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px'
                    }}></div>

                    <div className="relative z-10 max-w-full max-h-full p-4">
                      {result ? (
                         <div className="flex flex-col items-center">
                            <img src={result.url} alt="Processed" className="max-h-[500px] object-contain shadow-xl rounded-lg border border-slate-300" />
                            <div className="mt-4 bg-green-50 text-green-700 px-4 py-2 rounded-full text-sm font-medium border border-green-200 flex items-center">
                               <svg className="w-4 h-4 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>
                               Processed Successfully
                            </div>
                         </div>
                      ) : (
                        <div className="relative group">
                           <img src={currentFile.url} alt="Original" className="max-h-[500px] object-contain shadow-xl rounded-lg border border-slate-300 transition-transform duration-300" style={{
                             transform: `rotate(${options.rotate}deg) scaleX(${options.flipX ? -1 : 1}) scaleY(${options.flipY ? -1 : 1})`,
                             filter: `
                               grayscale(${options.grayscale ? 1 : 0}) 
                               blur(${options.blur}px)
                               ${options.sharpen ? 'contrast(1.2)' : ''}
                             `
                           }} />
                           {!result && <div className="absolute top-2 right-2 bg-black/60 text-white text-xs px-2 py-1 rounded backdrop-blur-sm">Preview</div>}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Actions Bar */}
                  {result && (
                    <div className="bg-white border border-slate-200 p-4 rounded-xl shadow-sm flex items-center justify-between animate-fade-in-up">
                       <div className="flex items-center gap-4">
                          <div className="text-sm">
                             <p className="text-slate-500">Original Size</p>
                             <p className="font-semibold text-slate-800">{formatSize(currentFile.size)}</p>
                          </div>
                          <div className="w-px h-8 bg-slate-200"></div>
                          <div className="text-sm">
                             <p className="text-slate-500">New Size</p>
                             <p className="font-semibold text-indigo-600">{formatSize(result.size)}</p>
                          </div>
                          <div className="w-px h-8 bg-slate-200"></div>
                          <div className="text-sm">
                             <p className="text-slate-500">Savings</p>
                             <p className="font-semibold text-green-600">
                               {currentFile.size > result.size 
                                 ? Math.round(((currentFile.size - result.size) / currentFile.size) * 100) + '%'
                                 : '-'}
                             </p>
                          </div>
                       </div>

                       <div className="flex gap-3">
                         <button 
                           onClick={handleReset}
                           className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 hover:bg-slate-100 rounded-lg transition-colors"
                         >
                           Start Over
                         </button>
                         <a 
                           href={result.url} 
                           download={result.filename}
                           className="flex items-center gap-2 bg-indigo-600 text-white px-6 py-2 rounded-lg font-semibold hover:bg-indigo-700 hover:shadow-lg hover:shadow-indigo-500/30 transition-all active:scale-95"
                         >
